import{_ as p,a0 as r,w as l,s as m,ao as a,I as i,x as o,a1 as n,A as s}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const k=JSON.parse('{"title":"Gentoo Linux 现在提供用于快速软件安装的二进制包 | LCTT x X-CMD","titleTemplate":false,"description":"Gentoo Linux 现在提供用于快速软件安装的二进制包 | LCTT (202401) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Gentoo Linux 现在提供用于快速软件安装的二进制包 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Gentoo Linux 现在提供用于快速软件安装的二进制包 | LCTT (202401) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202401/20231230 Big News- Gentoo Linux is Now Providing Binary Packages for Quick Software Installation","title":"Gentoo Linux 现在提供用于快速软件安装的二进制包","tag":"202401","desc":""},"relativePath":"202401/20231230 Big News- Gentoo Linux is Now Providing Binary Packages for Quick Software Installation.md","filePath":"[post].md"}'),g={name:"202401/20231230 Big News- Gentoo Linux is Now Providing Binary Packages for Quick Software Installation.md"};function u(d,t,f,x,w,G){const e=r("Link");return l(),m("div",null,[t[21]||(t[21]=a('<h1 id="gentoo-linux-现在提供用于快速软件安装的二进制包" tabindex="-1">Gentoo Linux 现在提供用于快速软件安装的二进制包 <a class="header-anchor" href="#gentoo-linux-现在提供用于快速软件安装的二进制包" aria-label="Permalink to “Gentoo Linux 现在提供用于快速软件安装的二进制包”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202401/03/142406n5k61kq3xddmu8mk.jpg" alt=""></p><blockquote><p>Gentoo 为硬件速度慢的用户准备了一份年终大礼。</p></blockquote><p>如果你不觉得这有什么大不了，那就说明你不了解 Gentoo。</p><p>Debian 有 deb 软件包，Fedora 有 RPM 软件包。甚至 Arch Linux 也提供了通过 Pacman 命令安装的二进制包。基本上，这些发行版从源代码构建这些包并将其提供给你。你可以使用发行版的包管理系统来获取这些二进制文件并将它们安装在你的系统上。</p><p>但进入 Gentoo 领域，情况就完全不同了。想要安装任何软件吗？ 你必须从源代码编译它。</p><p>是的，你没看错。这就是围绕编译和 Gentoo 产生了如此多的表情包的原因。</p><p><img src="https://news.itsfoss.com/content/images/2023/12/gentoo-ifi-it-moves-compile-it.png" alt="A blend of Gentoo and dad joke"></p><p>从源代码编译软件的问题意味着它将需要更多的计算能力。当你编译软件时，你的 CPU 将非常繁忙。</p><p><img src="https://news.itsfoss.com/content/images/2023/12/gentoo-compile-meme.png" alt=""></p><p>当然，编译一个软件需要一些时间。</p><p><img src="https://news.itsfoss.com/content/images/2023/12/gentoo-compile-time-meme.webp" alt="Image source: r/linuxmemes"></p><h3 id="现在你可以在-gentoo-中-安装-软件包而不是编译它们" tabindex="-1">现在你可以在 Gentoo 中“安装”软件包而不是编译它们 <a class="header-anchor" href="#现在你可以在-gentoo-中-安装-软件包而不是编译它们" aria-label="Permalink to “现在你可以在 Gentoo 中“安装”软件包而不是编译它们”">​</a></h3><p>Gentoo 的包管理器 Portage 多年来一直支持二进制包。只是没有预编译二进制包的集中仓库。</p><p>现在这种情况正在改变，因为 Gentoo 现在提供二进制包供下载和直接安装。</p>',15)),i("p",null,[t[1]||(t[1]=o("对于大多数架构，它将仅限于核心系统和每周更新。然而，对于 ",-1)),n(e,{href:"https://itsfoss.com/arm-aarch64-x86_64/"},{default:s(()=>[...t[0]||(t[0]=[o("amd64 和 arm64",-1)])]),_:1}),t[2]||(t[2]=o("，有一个为 LibreOffice、Docker、Plasma、GNOME 等流行软件提供二进制文件的巨大仓库。",-1))]),t[22]||(t[22]=i("p",null,"这对于使用低端硬件或不希望一直手动编译的 Gentoo 用户来说非常方便。",-1)),i("p",null,[t[4]||(t[4]=o("我知道你对在 Gentoo 中使用二进制包有很多疑问。查看 ",-1)),n(e,{href:"https://www.gentoo.org/news/2023/12/29/Gentoo-binary.html"},{default:s(()=>[...t[3]||(t[3]=[o("Gentoo 的官方公告",-1)])]),_:1}),t[5]||(t[5]=o("，其中包含详细内容。",-1))]),t[23]||(t[23]=a('<p><img src="https://www.gentoo.org/assets/img/logo/icon-192.png" alt=""></p><h3 id="基于源代码的安装不会消失" tabindex="-1">基于源代码的安装不会消失 <a class="header-anchor" href="#基于源代码的安装不会消失" aria-label="Permalink to “基于源代码的安装不会消失”">​</a></h3><p>先别生气，我的 Gentoo 伙计！你仍然可以享受从源代码编译的乐趣。这个选项不会消失。你仍然可以像以前一样享受编译的乐趣。二进制软件包是可选的。它们不会强迫你使用。</p><p>编译每一个包有其好处。软件针对其运行的系统进行了优化。这就是 Gentoo 用户所夸耀的性能提升。</p><p><img src="https://news.itsfoss.com/content/images/2023/12/gentoo-faster-meme.png" alt=""></p><p>由于系统资源有限，低端计算机需要更长的编译时间，但它也可以通过为机器构建每个软件来获得性能优化。如果你问我的话，这有点像第 22 条军规的情况。</p><h3 id="你用-gentoo-吗" tabindex="-1">你用 Gentoo 吗？ <a class="header-anchor" href="#你用-gentoo-吗" aria-label="Permalink to “你用 Gentoo 吗？”">​</a></h3><p>我坚信这不仅会为现有的 Gentoo 用户群带来便利，而且还将有助于扩大其用户群。毕竟，一个发行版用户在安装 Arch 之后会做什么呢？</p><p>我在这里的新闻报道中使用了很多表情包，因为现在是快乐的季节 ☃️</p><p>也许你可以利用寒假安装（但不编译）Gentoo 😜</p><p>享受节日和假期！</p><p><em>（题图：DA/389d8213-29fd-4149-b591-45e6cc9b0bb0）</em></p><hr>',13)),i("p",null,[t[7]||(t[7]=o("via: ",-1)),n(e,{href:"https://news.itsfoss.com/gentoo-binary-packages/"},{default:s(()=>[...t[6]||(t[6]=[o("https://news.itsfoss.com/gentoo-binary-packages/",-1)])]),_:1})]),i("p",null,[t[12]||(t[12]=o("作者：",-1)),n(e,{href:"https://news.itsfoss.com/author/root/"},{default:s(()=>[...t[8]||(t[8]=[o("Abhishek",-1)])]),_:1}),t[13]||(t[13]=o(" 选题：",-1)),n(e,{href:"https://github.com/lujun9972"},{default:s(()=>[...t[9]||(t[9]=[o("lujun9972",-1)])]),_:1}),t[14]||(t[14]=o(" 译者：",-1)),n(e,{href:"https://github.com/geekpi"},{default:s(()=>[...t[10]||(t[10]=[o("geekpi",-1)])]),_:1}),t[15]||(t[15]=o(" 校对：",-1)),n(e,{href:"https://github.com/wxy"},{default:s(()=>[...t[11]||(t[11]=[o("wxy",-1)])]),_:1})]),i("p",null,[t[18]||(t[18]=o("本文由 ",-1)),n(e,{href:"https://github.com/LCTT/TranslateProject"},{default:s(()=>[...t[16]||(t[16]=[o("LCTT",-1)])]),_:1}),t[19]||(t[19]=o(" 原创编译，",-1)),n(e,{href:"https://linux.cn/"},{default:s(()=>[...t[17]||(t[17]=[o("Linux中国",-1)])]),_:1}),t[20]||(t[20]=o(" 荣誉推出",-1))])])}const P=p(g,[["render",u]]);export{k as __pageData,P as default};
